def to_orig(i, j, L):
    st = n - j      # original coord of rc[j] (1-based)
    en = n - i
    return st, en, L

minus_orig = [to_orig(i, j, L) for (i, j, L) in minus_orfs_rc]

plus_orfs.sort(key=lambda o: -o[2])
minus_orig.sort(key=lambda o: -o[2])

