# Shine-Dalgarno consensus actual E. coli end-16S: 5' AUCACCUCCUUA-3' ~ CCUCC
# common strong SD: AGGAGG (max), typical range AGGAG / GGAG / AGGA
sd_patterns = ['AGGAGG','AGGAG','GGAGG','AAGGAGT','AGGTG','GGAG','AGGA','GAGG','GGGT','GGTG','AAGG']

def upstream_win(seq_strand, atg_idx0, lo=4, hi=15):
    # window from atg_idx0-hi .. atg_idx0-lo within which SD should lie
    return seq_strand[max(0,atg_idx0-hi): max(0,atg_idx0-lo)]

