        c = strand[i:i+3]
        if c == 'ATG' or c == 'GTG' or c == 'TTG':
            win = upstream_win(strand, i)
            hit = None
            for p in sd_patterns:
                if p in win:
                    hit = (win, p)
                    break
            if hit:
                # gene length: this start to run to next stop (any downstream stop)
                j = i+3
                while j+3 <= len(strand) and strand[j:j+3] not in {'TAA','TAG','TGA'}:
                    j += 3
                L = (j+3-i) if j+3 <= len(strand) else (len(strand)-i)
                if L >= 90:
