n = len(s)

# Find all ATG positions on each strand, then use whichever have reasonable length ORFs
def all_starts(x, motif='ATG'):
    return [i for i in range(len(x)-2) if x[i:i+3]==motif]

def length_from(x, i):
    j = i
    while j+3 <= len(x) and x[j:j+3] not in {'TAA','TAG','TGA'}:
        j += 3
    return (j - i)

# Plus strand ATGs
plus_atgs = all_starts(s)
# Minus strand in rc coords; map back
rcs = rcseq(s)
minus_atgs_rc = all_starts(rcs)

def toc(i0, strand, L):
    if strand == '+':
        return i0+1, i0+L
    else:
        return n-(i0+L)+1, n-i0

print("Plus ATG candidates with in-frame ORF length >= 240 nt:")
rows = []
for i in plus_atgs:
    L = length_from(s, i)
    if L >= 240:
        rows.append((i+1, L, '+'))
for i in minus_atgs_rc:
    L = length_from(rcs, i)
    if L >= 240:
        a, b = toc(i, '-', L)
        rows.append((a, L, '-'))
rows.sort()
for a, L, st in rows:
    print(f"  {st}  start-ATG at {a}, ORF runs {L} nt ({L//3} codons)")
